local _, WFJ = ...
WFJ.Data.add("book", {
  ["f4057b774c970a48"] = { "Non dobbiamo dare più informazioni a Thorsen, e dobbiamo ucciderlo. Non è più di alcuna utilità per il nostro colonnello. Farò fuori Thorsen se ne avrò l'occasione, ma se ricevi questa lettera saprai che non ho ancora potuto farlo. In tal caso, suggerisco che il prossimo incontro di Thorsen con i nostri agenti sia fatale. Lunga vita a Kurzen, -M", "." },
  ["f46def3be4c308d6"] = { "Kil'jaeden sapeva che i clan degli orchi erano quasi pronti, ma doveva essere certo della loro lealtà assoluta. In segreto fece evocare dal ⟦Shadow Council=Concilio dell'Ombra⟧ Mannoroth il Distruttore, vivente ricettacolo di distruzione e di furia. Gul'dan riunì i capi clan e li convinse che bere il sangue furioso di Mannoroth li avrebbe resi del tutto invincibili.", "." },
  ["f47d4886cff2ddf1"] = { "Scegliendo di seguire il proprio istinto, Lothar diede l'assalto a Karazhan, la torre fortezza di Medivh, con l'aiuto del giovane apprendista del mago, Khadgar. Khadgar e Lothar riuscirono a sconfiggere il Guardiano posseduto, che ebbero la conferma essere l'origine del conflitto.", "." },
  ["f4ca3fe2e1628782"] = { "Dorgar Stoenbrow\n\nGuerriero della ⟦Scarlet Crusade=Crociata Scarlatta⟧\n\nSignore delle Red Caverns\n\nVisto l'ultima volta sulle Montagne d'Alterac", "." },
  ["f4d05f591202f904"] = { "Appresa dai magocrati la notizia dell'attività demoniaca a Dalaran, gli elfi inviarono subito nelle terre degli umani i loro maghi più potenti. I maghi elfici studiarono le correnti di energia di Dalaran e redassero rapporti dettagliati su tutta l'attività demoniaca che osservarono. Conclusero che, sebbene nel mondo circolassero solo pochi demoni, la Legione stessa sarebbe rimasta una minaccia terribile finché gli umani avessero continuato a usare le forze della magia.", "." },
  ["f4e901d2bf18266e"] = { "Arcivescovo Alonsus Faol\n\nBenevolo patrono della Chiesa della Luce.\n\nSebbene avesse iniziato la sua opera di bene a Stratholme, in Lordaeron, l'arcivescovo Faol fu un grande amico del popolo di ⟦Stormwind=Roccavento⟧. Nei giorni bui dopo la Seconda Guerra, contribuì a riformare la Fratellanza della ⟦Northshire=Contea del Nord⟧ e raccolse ingenti fondi per ricostruire la stessa città di ⟦Stormwind=Roccavento⟧.\n\nQuesta Cattedrale si erge non solo come baluardo della ⟦Holy Light=Luce Sacra⟧, ma anche come testimonianza duratura dello spirito nobile e della generosità di un uomo.", "." },
})
